import { createRequire } from 'node:module'

const packageMetadata = createRequire(import.meta.url)('../package.json') as { version: string }

export const applicationVersion = packageMetadata.version

// @vitest-environment node
import { describe, expect, it, vi } from 'vitest'
import { createShutdownHandler } from './shutdown.js'

function deferred() {
  let resolve!: () => void
  const promise = new Promise<void>((complete) => {
    resolve = complete
  })
  return { promise, resolve }
}

describe('createShutdownHandler', () => {
  it('runs shutdown only once for duplicate signals', async () => {
    const close = vi.fn(async () => undefined)
    const app = {
      close,
      log: { info: vi.fn(), warn: vi.fn() },
      server: { closeAllConnections: vi.fn() },
    }
    const shutdown = createShutdownHandler({ app: app as never })
    const first = shutdown('SIGINT')
    const second = shutdown('SIGTERM')
    expect(first).toBe(second)
    await first
    expect(close).toHaveBeenCalledTimes(1)
    expect(app.log.info).toHaveBeenCalledWith('graceful shutdown completed')
  })

  it('bounds shutdown and closes active connections after the timeout', async () => {
    const pendingClose = deferred()
    const closeAllConnections = vi.fn(() => pendingClose.resolve())
    const app = {
      close: vi.fn(() => pendingClose.promise),
      log: { info: vi.fn(), warn: vi.fn() },
      server: { closeAllConnections },
    }
    const shutdown = createShutdownHandler({ app: app as never, timeoutMs: 5 })
    await shutdown('SIGTERM')
    expect(closeAllConnections).toHaveBeenCalledOnce()
    expect(app.log.warn).toHaveBeenCalledWith(
      { timeoutMs: 5 },
      'graceful shutdown timed out; closing active connections',
    )
  })
})

import type { FastifyInstance } from 'fastify'

export interface ShutdownOptions {
  app: Pick<FastifyInstance, 'close' | 'log' | 'server'>
  timeoutMs?: number
}

export function createShutdownHandler({ app, timeoutMs = 10_000 }: ShutdownOptions) {
  let shutdownPromise: Promise<void> | undefined

  return (signal: NodeJS.Signals): Promise<void> => {
    shutdownPromise ??= runShutdown(app, signal, timeoutMs)
    return shutdownPromise
  }
}

async function runShutdown(
  app: ShutdownOptions['app'],
  signal: NodeJS.Signals,
  timeoutMs: number,
): Promise<void> {
  app.log.info({ signal }, 'graceful shutdown started')
  const closePromise = app.close()
  let timedOut = false
  let timeout: NodeJS.Timeout | undefined

  await Promise.race([
    closePromise,
    new Promise<void>((resolve) => {
      timeout = setTimeout(() => {
        timedOut = true
        resolve()
      }, timeoutMs)
      timeout.unref()
    }),
  ])

  if (timeout) clearTimeout(timeout)
  if (timedOut) {
    app.log.warn({ timeoutMs }, 'graceful shutdown timed out; closing active connections')
    app.server.closeAllConnections()
    await closePromise
  }
  app.log.info('graceful shutdown completed')
}

